"""
CompoundCache — reuses accumulated facts to skip redundant queries.
Queries decision-vectors.db for matching dimension + domain.
Also merges brainstorm_claims + brainstorm_mechanisms for continuity across sessions.
"""

import json
import sqlite3
from datetime import datetime, timezone
from difflib import SequenceMatcher
from pathlib import Path
from typing import Optional

from ..hunger.claim_parser import ParsedClaim

ROOT = Path(__file__).resolve().parents[4]
VECTORS_DB = ROOT / ".claude" / "data" / "knowledge-distillation" / "decision-vectors.db"

FRESHNESS_MAX_DAYS = 180

DIM_MAP = {
    "base_rates": "failure_rates", "failure_patterns": "failure_rates",
    "competitive_landscape": "competitive_landscape",
    "unit_economics": "unit_economics", "moat_patterns": "moat_patterns",
    "timing_windows": "timing_windows", "regulatory_risks": "regulatory_risks",
    "compounding_mechanisms": "compounding_mechanisms",
    "career_path": "founder_paths", "founder_experience": "founder_paths",
    "capital_requirements": "unit_economics",
    "execution_distance": "founder_paths", "leverage_type": "compounding_mechanisms",
    "network_access": "founder_paths", "indirect_entry": "founder_paths",
    "deal_skills": "unit_economics",
}


def _is_fresh(created_at: Optional[str], now: datetime) -> bool:
    if not created_at:
        return True
    try:
        dt = datetime.fromisoformat(created_at.replace("Z", "+00:00"))
        return (now - dt).days <= FRESHNESS_MAX_DAYS
    except (ValueError, TypeError):
        return True


def _similarity(a: str, b: str) -> float:
    return SequenceMatcher(None, a.lower().strip(), b.lower().strip()).ratio()


class CompoundCache:
    def __init__(self, db_path: Optional[Path] = None):
        self.db_path = db_path or VECTORS_DB

    def lookup(self, dimension: str, context: dict) -> list[ParsedClaim]:
        if not self.db_path.exists():
            return []

        claim_dim = DIM_MAP.get(dimension, dimension)
        industry = context.get("industry", "")
        now = datetime.now(timezone.utc)

        results = self._query_decision_vectors(claim_dim, industry, now)
        brainstorm = self._query_brainstorm_claims(dimension, context, now)
        mechanisms = self._query_brainstorm_mechanisms(context)

        merged = _deduplicate(results + brainstorm + mechanisms, threshold=0.90)
        return sorted(merged, key=lambda c: -c.confidence)

    def cache_hit_rate(self, domain: str) -> float:
        if not self.db_path.exists():
            return 0.0
        try:
            with sqlite3.connect(str(self.db_path)) as conn:
                total = conn.execute(
                    "SELECT COUNT(*) FROM decision_vectors WHERE industry=?",
                    (domain,),
                ).fetchone()[0]
            return min(1.0, total / 50.0)
        except sqlite3.DatabaseError:
            return 0.0

    # ------------------------------------------------------------------
    # Private helpers
    # ------------------------------------------------------------------

    def _query_decision_vectors(self, claim_dim: str, industry: str, now: datetime) -> list[ParsedClaim]:
        try:
            with sqlite3.connect(str(self.db_path)) as conn:
                rows = conn.execute(
                    "SELECT features_json, created_at FROM decision_vectors "
                    "WHERE industry=? ORDER BY created_at DESC LIMIT 20",
                    (industry,),
                ).fetchall()
        except sqlite3.DatabaseError:
            return []

        results = []
        for features_json, created_at in rows:
            try:
                features = json.loads(features_json)
            except (json.JSONDecodeError, TypeError):
                continue
            if features.get("dimension", "") != claim_dim:
                continue
            if not _is_fresh(created_at, now):
                continue
            fact_text = features.get("fact", features.get("description", ""))
            if not fact_text:
                continue
            results.append(ParsedClaim(
                fact=fact_text,
                value=self._parse_float(features.get("value")),
                dimension=claim_dim,
                source_url=features.get("source_url"),
                source_date=features.get("source_date"),
                confidence=features.get("confidence", 0.6),
                zone_tag=features.get("zone_tag", "T"),
            ))
        return results

    def _query_brainstorm_claims(self, dimension: str, context: dict, now: datetime) -> list[ParsedClaim]:
        claim_dim = DIM_MAP.get(dimension, dimension)
        try:
            with sqlite3.connect(str(self.db_path)) as conn:
                rows = conn.execute(
                    "SELECT fact, dimension, zone_tag, confidence, source_url, created_at "
                    "FROM brainstorm_claims WHERE dimension=? ORDER BY created_at DESC LIMIT 30",
                    (claim_dim,),
                ).fetchall()
        except sqlite3.OperationalError:
            # Table doesn't exist yet — graceful fallback
            return []
        except sqlite3.DatabaseError:
            return []

        results = []
        for fact, dim, zone_tag, confidence, source_url, created_at in rows:
            if not fact or not _is_fresh(created_at, now):
                continue
            results.append(ParsedClaim(
                fact=fact,
                dimension=dim or claim_dim,
                zone_tag=zone_tag or "T",
                confidence=self._parse_float(confidence) or 0.5,
                source_url=source_url,
            ))
        return results

    def _query_brainstorm_mechanisms(self, context: dict) -> list[ParsedClaim]:
        topic = context.get("topic", context.get("industry", ""))
        try:
            with sqlite3.connect(str(self.db_path)) as conn:
                rows = conn.execute(
                    "SELECT mechanism, bottleneck_node, money_flow FROM brainstorm_mechanisms "
                    "WHERE topic LIKE ? ORDER BY created_at DESC LIMIT 10",
                    (f"%{topic}%",),
                ).fetchall()
        except sqlite3.OperationalError:
            # Table doesn't exist yet — graceful fallback
            return []
        except sqlite3.DatabaseError:
            return []

        results = []
        for mechanism, bottleneck_node, money_flow in rows:
            parts = [p for p in [mechanism, bottleneck_node, money_flow] if p]
            if not parts:
                continue
            fact_text = " | ".join(parts)
            results.append(ParsedClaim(
                fact=fact_text,
                dimension="mechanism_context",
                zone_tag="T",
                confidence=0.55,
            ))
        return results

    def _parse_float(self, val) -> Optional[float]:
        if val is None:
            return None
        try:
            return float(val)
        except (TypeError, ValueError):
            return None


def _deduplicate(claims: list[ParsedClaim], threshold: float = 0.90) -> list[ParsedClaim]:
    unique: list[ParsedClaim] = []
    for claim in claims:
        is_dup = any(
            _similarity(claim.fact, existing.fact) >= threshold
            for existing in unique
        )
        if not is_dup:
            unique.append(claim)
    return unique
